"""Noticias: clasificación real por texto y panel lateral repartido por fuente

Ejecutar desde la raíz del proyecto:   python instalar_noticias_clasificacion.py
Idempotente, sin .bak. No instala nada si algún archivo difiere de la versión esperada.
"""
import base64, hashlib, io, json, os, sys, zipfile

PRE = {'componentes_plataforma/noticias/articulo.py': 'fbccf678d6f01aa5e20107788c932763de8aba19a6e140f1c76de21518e7da7a', 'componentes_plataforma/noticias/datos.py': '9f930b2e87d400553a3ed7561f2ad1d417b177dca95b4c3d3c85d79061b1dd91', 'componentes_plataforma/noticias/fuentes.json': 'a4bf47e70a68f0a56c897ddf3796540aef7bd68d73f18585193adc2dad5afc5c', 'componentes_plataforma/noticias/modal.py': 'b257ac45c73674ae9546aa6a9241ac945667fa344802057edeaf0e3b9f43dd8a', 'componentes_plataforma/noticias/rss.py': '8d5738ddfdbe0fd6a13a6681fb36594fd7c73395616c20e7d32b8fd7aaa787c6', 'componentes_plataforma/noticias/secciones.py': 'a287049aa42fe485ced2636a30050145e766b80cff15465d26ed09ddec15f920'}
ARCHIVOS = ["componentes_plataforma/noticias/articulo.py", "componentes_plataforma/noticias/datos.py", "componentes_plataforma/noticias/fuentes.json", "componentes_plataforma/noticias/modal.py", "componentes_plataforma/noticias/rss.py", "componentes_plataforma/noticias/secciones.py"]
ZIP_B64 = ""


def norm(b):
    return b.replace(b"\r\n", b"\n")


def main():
    z = zipfile.ZipFile(io.BytesIO(base64.b64decode(ZIP_B64)))
    nuevos = {f: norm(z.read(f)) for f in ARCHIVOS}
    if all(os.path.exists(f) and norm(open(f, "rb").read()) == nuevos[f] for f in ARCHIVOS):
        print("Ya estaba instalado: no hay nada que hacer.")
        return
    problemas = []
    for f, h in PRE.items():
        if h is None:
            if os.path.exists(f):
                problemas.append("ya existe " + f)
        elif not os.path.exists(f):
            problemas.append("falta " + f)
        elif hashlib.sha256(norm(open(f, "rb").read())).hexdigest() != h:
            problemas.append(f + " difiere de la versión esperada (¿cambios sin subir?)")
    if problemas:
        print("No se instaló nada:")
        for p in problemas:
            print("  -", p)
        sys.exit(1)
    for f in ARCHIVOS:
        datos = nuevos[f]
        os.makedirs(os.path.dirname(f) or ".", exist_ok=True)
        if os.path.exists(f) and b"\r\n" in open(f, "rb").read():
            datos = datos.replace(b"\n", b"\r\n")
        with open(f, "wb") as fh:
            fh.write(datos)
    print("Listo: %d archivos actualizados." % len(ARCHIVOS))


if __name__ == "__main__":
    main()
